package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.view.*;
/** Exported standard timer entry, always reviewed. No incoming request starts or replaces a timer. */
public final class TimerRequestActivity extends Activity {
 private TimerRequest request;private int minutes;private String error="";private Dialog picker;private Bundle restoredPicker;private boolean handed;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);if(saved==null)read(getIntent());else try{request=saved.getBoolean("valid")?new TimerRequest(saved.containsKey("seconds")?saved.getInt("seconds"):null,saved.getString("message",""),saved.getBoolean("skip")):null;minutes=saved.getInt("minutes");if(minutes<0||minutes>600)throw new IllegalArgumentException();error=saved.getString("error","");restoredPicker=saved.getBundle("picker");}catch(RuntimeException invalid){request=null;minutes=0;error="This timer draft could not be restored. Open a new request.";}render();if(restoredPicker!=null&&request!=null){Bundle savedPicker=restoredPicker;restoredPicker=null;chooseDuration();if(picker instanceof SleepPicker.StateDialog)picker.onRestoreInstanceState(savedPicker);}}
 private void read(Intent intent){handed=false;try{request=TimerRequestInput.read(intent);minutes=request.exactMinutes();error="";}catch(RuntimeException invalid){request=null;minutes=0;error=invalid.getMessage()==null?"This timer request could not be read.":invalid.getMessage();}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);if(picker!=null){picker.dismiss();picker=null;}setIntent(intent);restoredPicker=null;read(intent);render();}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Review timer request",this::finish);Design.space(body,18);if(request==null){Design.text(body,"Timer request unavailable",23,600,Design.INK);Design.text(body,error,14,500,Design.MUTED);Design.fixedAction(body,"Close",this::finish);return;}if(request.seconds==null)Design.text(body,"Choose a timer duration",24,600,Design.INK);else{Design.text(body,"Requested "+requestedLength(request.seconds),24,600,Design.INK);if(request.exactMinutes()==0){Design.space(body,10);Design.text(body,request.seconds>36000?"SleepWell’s nap timer supports at most 10 hours. Choose a shorter duration to continue.":"SleepWell’s nap timer supports whole minutes. Choose an alternative explicitly; seconds will not be rounded silently.",14,500,Design.BROWN);int suggestion=request.suggestedMinutes();if(suggestion>0)Design.button(body,"Choose "+PlanActivity.duration(suggestion)+" instead",false,()->{minutes=suggestion;error="";render();});}}Design.space(body,16);Design.item(body,"clock","Selected duration",minutes==0?"Not chosen":PlanActivity.duration(minutes),this::chooseDuration);Design.line(body);Design.item(body,"keyboard","Timer message",request.message.isEmpty()?"No message":request.message,this::chooseMessage);Design.line(body);Design.space(body,12);Design.text(body,"This opens a new nap draft with the selected duration and message. Review its sound and challenge, then tap Start nap. Your other alarms and timers stay saved.",14,400,Design.MUTED);Design.space(body,10);Design.text(body,request.skipRequested?"The requesting app asked to skip setup. SleepWell still requires this review and a separate Start action.":"No timer starts until you confirm it in SleepWell.",12,400,Design.MUTED);LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty()){TextView issue=Design.text(footer,error,13,500,0xffa93919);issue.setContentDescription("Timer request error");issue.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}Button next=Design.button(footer,"Review nap settings",true,this::continueDraft);RecordUi.enabled(next,minutes>0&&!handed);Design.button(footer,"Cancel request",false,this::finish);}
 private String requestedLength(int seconds){return seconds%60==0?PlanActivity.duration(seconds/60):seconds<60?seconds+" sec":seconds/60+" min "+seconds%60+" sec";}
 private void chooseDuration(){if(request==null)return;if(picker!=null)picker.dismiss();picker=SleepPicker.duration(this,"Timer duration",minutes==0?20:minutes,1,600,n->{minutes=n;error="";render();});}
 private void chooseMessage(){if(request==null)return;if(picker!=null)picker.dismiss();picker=SleepPicker.name(this,request.message.isEmpty()?"Timer":request.message,n->{try{request=new TimerRequest(request.seconds,n,request.skipRequested);error="";}catch(IllegalArgumentException invalid){error=invalid.getMessage();}render();});}
 private void continueDraft(){if(handed||!hasWindowFocus()||request==null)return;try{Intent clean=TimerRequestDraft.open(this,minutes,request.message);handed=true;startActivity(clean);finish();}catch(RuntimeException unavailable){handed=false;error="The nap draft could not open. Try again or cancel this request.";render();}}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("valid",request!=null);if(request!=null){if(request.seconds!=null)state.putInt("seconds",request.seconds);state.putString("message",request.message);state.putBoolean("skip",request.skipRequested);}state.putInt("minutes",minutes);state.putString("error",error);if(picker instanceof SleepPicker.StateDialog&&picker.isShowing())state.putBundle("picker",picker.onSaveInstanceState());}
 @Override protected void onDestroy(){if(picker!=null)picker.dismiss();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
